def _skill_knowledge_files(workdir: Path) -> list[Path]:
    out: list[Path] = []
    for p in [
        workdir / "agents" / "s05_skill_loading.py",
        workdir / "agents" / "s_full.py",
    ]:
        if p.exists():
            out.append(p)
    docs_dir = workdir / "docs"
    if docs_dir.exists():
        out.extend(sorted(docs_dir.rglob("s05-skill-loading.md")))
    dedup: list[Path] = []
    seen: set[str] = set()
    for p in out:
        key = str(p.resolve())
        if key in seen:
            continue
        seen.add(key)
        dedup.append(p)
    return dedup

